class Plot:
    def __init__(self):
        self.w = 2
        self.h = 3
    @property
    def area(self):
        return self.w * self.h
plot = Plot()
assert plot.area == 6

class P:
    @property
    def area(self):
        return self._area
    @area.setter
    def area(self, v):
        if v <= 0:
            raise ValueError
        self._area = v
p = P()
p.area = 5
assert p.area == 5
try:
    p.area = -1
    assert False
except ValueError:
    pass

class P:
    @property
    def age(self):
        return self._age
    @age.setter
    def age(self, v):
        self.age = v
p = P()
try:
    p.age = 1
    assert False
except RecursionError:
    pass

calls = []
class A:
    def __init__(s, v):
        s.v = v
    def __lt__(s, o):
        calls.append('lt')
        return s.v < o.v
    def __gt__(s, o):
        calls.append('gt')
        return s.v > o.v
xs = [A(1), A(2), A(3)]
sorted(xs)
assert set(calls) == {'lt'}
calls.clear()
min(xs)
assert set(calls) == {'lt'}
calls.clear()
max(xs)
assert set(calls) == {'gt'}

class A:
    pass
for f in (sorted, max, min):
    try:
        f([A(), A()])
        assert False
    except TypeError:
        pass

class B:
    def __init__(s, n):
        s.name = n
bs = [B('b'), B('a')]
assert [b.name for b in sorted(bs, key=lambda b: b.name)] == ['a', 'b']

def k(x):
    return len(x)
assert sorted(['ccc', 'a', 'bb'], key=k) == ['a', 'bb', 'ccc']

class A:
    def __init__(s, v):
        s.v = v
    def __lt__(s, o):
        return s.v < o.v
assert [a.v for a in sorted([A(2), A(1)])] == [1, 2]

class A:
    def __init__(s, v):
        s.v = v
    def __lt__(s, o):
        return s.v < o.v
a, b = A(2), A(1)
assert (a > b) is True
assert max([b, a]) is a
assert min([a, b]) is b
assert sorted([a, b]) == [b, a]

